		let min_dist = 0.075
		if (d1 > min_dist && d2 > min_dist && d3 > min_dist ) {
			return
		}
	}

	closest_drag = 3
	if (d1 < d2 && d1 < d3)
		closest_drag = 1
	else if (d2 < d1 && d2 < d3)
		closest_drag = 2


	if (closest_drag === 1) {
		circle_data_1["x"] = mx
		circle_data_1["y"] = my
	}
	else if (closest_drag === 2) {
		circle_data_2["x"] = mx
		circle_data_2["y"] = my
	}
	else {
		circle_data_3["x"] = mx
		circle_data_3["y"] = my
	}
}


