// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision mediump float;
#endif

attribute vec3 aPosition;

// Always include this to get the position of the pixel
void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);

  // scale the rect by two, and move it to the center of the screen
  // if we don't do this, it will appear with its bottom left corner in the center of the sketch
  // try commenting this line out to see what happens
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // Send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}


// === Tab: frag.glsl ===
// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision mediump float;
#endif

// In this example we care about where on the canvas the pixel is, so we need to know the size of the canvas.
// This is passed in as a uniform from the sketch.js file.
uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform float lower_bar_pct;

uniform vec3 circle_geo_1;
uniform vec3 circle_geo_2;
uniform vec3 circle_geo_3;
uniform vec4 circle_col_1;
uniform vec4 circle_col_2;
uniform vec4 circle_col_3;
uniform vec3 circle_dat_1;
uniform vec3 circle_dat_2;
uniform vec3 circle_dat_3;


float sdf_circle(vec2 fragcoord, vec2 center, float r) {
	// SDF for circle. Value 0 at edge.
  vec2 dxy = fragcoord - center;
	return length(dxy) - r;
}


float positive_banding(float d, float bf) {
	// Creates banding from input. Higher bf more bands.
	// Returns 0..1
	return 2.0*abs(fract(bf*d)-0.5);
}


void main() {
  // position of the pixel divided by resolution, to get normalized positions on the canvas
	// giving coords (0,0) lower left and (1,1) upper right
	// but a circle won't be a circle.
	//	vec2 uv = gl_FragCoord.xy/u_resolution.xy;

	// (-1.., -1) lower left to (1.., 1) upper right (y goes from -1..1, x whatever the resolution was).
	vec2 uv;
	uv.x = (gl_FragCoord.x * 2.0 - u_resolution.x) / u_resolution.y;
	uv.y = (gl_FragCoord.y * 2.0 - u_resolution.y) / u_resolution.y;

	vec2 uv_mouse = (u_mouse.xy * 2.0 - u_resolution.xy) / u_resolution.y;

	// Dont draw on the lower part of screen. Better solved in p5/html
	if (uv.y < (lower_bar_pct*2. - 1.)) return;

  // Lets use the pixels position on the x-axis as our gradient for the red color
  // Where the position is closer to 0.0 we get black (st.x = 0.0)
  // Where the position is closer to width (defined as 1.0) we get red (st.x = 1.0)
  gl_FragColor = vec4(uv.x,0.0,0.0,1.0); // R,G,B,A

  // you can only have one gl_FragColor active at a time, but try commenting the others out
  // try the green channel
  //gl_FragColor = vec4(0.0,uv.x,0.0,1.0); 

  // try both the x position and the y position
  gl_FragColor = vec4(uv.x,uv.y,0.0,1.0); 

	// Circle with negative inside and increasingly positive outside.
	//vec3 circle = vec3(0.0, 0.5, 0.05);
	//float d = sdf_circle(uv, circle.xy, circle.z);

	// Black non-negative sdf mask, but increasingly positive.
	//d = max(0.0, d);

	// step(edge, x) step outputs 0/1. 0.0 if x < edge, else 1.0
	//d = step(0.0, d);

	// Smoothed edges around 0, but allowed negative values.
	//float sf = 0.01;
	//d = smoothstep(-sf, sf, d); // edge 0, edge 1, x

	// Smoothed edges around "0", no negative values.
	//float sf = 0.01;
	//d = smoothstep(0.0, 2.0*sf, d); // edge 0, edge 1, x

	// Make banding outside the shape. Starts over 0..1, 0..1
	//d = max(0.0, d);
	//d = fract(20.0*d);

	// Circles
	float d;
	vec3 circle;
	float r = 0.05;


	// C1
	// Convert the input to the selected precision.
	vec3 circle_geo_1_p = vec3(circle_geo_1);	
	vec4 circle_col_1_p = vec4(circle_col_1);
	vec3 circle_dat_1_p = vec3(circle_dat_1);

	circle = vec3(-1., 0.5, 0.05);
	circle = vec3(circle_geo_1_p[0], circle_geo_1_p[1], r);
	d = sdf_circle(uv, circle.xy, circle.z);
	// Make the banding 0..1..0..1..
	// This will however make the shape 1 in the center because the 0 there will become a 1.
	// So remember the original inside.
	float d0 = step(0.0, d);	// Black inner mask
	d = positive_banding(d, circle_geo_1_p[2]);

	// C2
	// Convert the input to the selected precision.
	vec3 circle_geo_2_p = vec3(circle_geo_2);	
	vec4 circle_col_2_p = vec4(circle_col_2);
	vec3 circle_dat_2_p = vec3(circle_dat_2);

	circle = vec3(-1., -0.5, 0.05);
	circle = vec3(circle_geo_2_p[0], circle_geo_2_p[1], r);
	float d2 = sdf_circle(uv, circle.xy, circle.z);
	float d2_0 = step(0.0, d2);	// Black inner mask
	d2 = positive_banding(d2, circle_geo_2_p[2]);

	// C3
	// Convert the input to the selected precision.
	vec3 circle_geo_3_p = vec3(circle_geo_3);	
	vec4 circle_col_3_p = vec4(circle_col_3);
	vec3 circle_dat_3_p = vec3(circle_dat_3);

	//circle = vec3(-0.5*sqrt(3.0), -0.0, 0.05);
	circle = vec3(-1., 0.0, 0.05);
	circle = vec3(circle_geo_3_p[0], circle_geo_3_p[1], r);
	float d3 = sdf_circle(uv, circle.xy, circle.z);
	float d3_0 = step(0.0, d3);	// Black inner mask
	d3 = positive_banding(d3, circle_geo_3_p[2]);

	// Add the bandings, normalise

	// Allow negaitve interferenc
	//d -= 0.5;
	//d2 -= 0.5;
	//d3 -= 0.5;
	//d = (d + d2 + d3) / 1.5;
	float ds = (d + d2 + d3) / 3.0;

	// Black out inner masks afterwards
	ds *= d0;
	ds *= d2_0;
	ds *= d3_0;

	// Each point irradiates a primary color
	gl_FragColor.xyz = vec3(d,d2,d3);

	// Each point irradiates a secondary color
	d  = pow( d, circle_dat_1_p[0]);
	d2 = pow(d2, circle_dat_2_p[0]);
	d3 = pow(d3, circle_dat_3_p[0]);

	vec3 col_c1 = circle_col_1.xyz / 255.0;
	vec3 col_c2 = circle_col_2.xyz / 255.0;
	vec3 col_c3 = circle_col_3.xyz / 255.0;

	gl_FragColor.xyz = d*col_c1 + d2*col_c2 + d3*col_c3;

	// Brighten
	gl_FragColor.xyz *= 1.3;

	return;



//gl_FragColor.xyz = vec3(ds,ds,ds);
	// debug color if any value is oversaturated.
	if (gl_FragColor.x > 1.0 || gl_FragColor.y > 1.0 || gl_FragColor.z > 1.0) {
		gl_FragColor.xyz = vec3(1.0, 0.0, 1.0);		  
	}
	return;



	// White mask for the circle.
	// step(T edge, T x) 0.0 if x < edge, else 1.0
	//d = step(d, 0.0);

	// Black mask for the circle
	d = step(1.0-d, 0.0);

	gl_FragColor.xyz = vec3(d,d,d);
}

